"use strict";

angular
	.module("irtech.netcity.school.calendar")
	.controller("VacationsClassesCtrl", ($scope, $http, $document, $location, $appLoader, vacationsRepository, $q, $alerts) => {


		$scope.$parent.page = {
			title: language.SetupSchoolCalendar.kVacationsClasses,
			parent: {
				title: language.Generic.MenuFolders.kFNSchoolYearAndTerms,
				href: `/asp/SetupSchool/Calendar/Years.asp`
			},
			back: { history: false }
		};

		$scope.userId = appContext.userId;

		$.extend($scope, {
			language: language,
			funcType: appContext.funcType,
			data: {
				classes: [],
				classesIds: [],
				grades: [],
				vacations: [],
				vacationsIds: [],
				classesVacations: [],
				classVacationMatrix: [],
				classVacationEtalonMatrix: [],
				classVacationColorMatrix: [],
				classesIndexDictionary: null,
				vacationsIndexDictionary: null,
				gradesChecks: [],
				vacationsChecks: [],
				classesChecks: []
			},
			state: {
				dataReady: false,
				emptyData: true
			}
		});

		$scope.getGradeCheckCondition = (grade) => {
			const firstClassIdByGrade = _.find($scope.data.classes, (cls) => cls.grade.id === grade).id;
			const classesByGradeAmount = _.filter($scope.data.classes, (cls) => cls.grade.id === grade).length;
			const firstClassIndexByGrade = _.indexOf($scope.data.classesIds, firstClassIdByGrade);
			let trueFlag = true;
			let falseFlag = false;
			for (let i = firstClassIndexByGrade; i < firstClassIndexByGrade + classesByGradeAmount; i++) {
				for (let j = 0; j < $scope.data.vacations.length; j++) {
					trueFlag = trueFlag && $scope.data.classVacationMatrix[i][j];
					falseFlag = falseFlag || $scope.data.classVacationMatrix[i][j];
				}
			}
			return trueFlag
				? true
				: falseFlag ? null : false;
		}

		$scope.changeMatrixColors = () => {
			for (let i = 0; i < $scope.classes.length; i++) {
				for (let j = 0; j < $scope.vacations.length; j++) {
					$scope.classVacationColorMatrix[i][j] = $scope.classVacationMatrix[i][j] !== $scope.classVacationEtalonMatrix[i][j];
				}
			}
		}

		$scope.getVacationCheckCondition = (vacation) => {
			const vacationIndex = _.indexOf($scope.data.vacationsIds, vacation);
			let trueFlag = true;
			let falseFlag = false;
			for (let i = 0; i < $scope.data.classes.length; i++) {
				trueFlag = trueFlag && $scope.data.classVacationMatrix[i][vacationIndex];
				falseFlag = falseFlag || $scope.data.classVacationMatrix[i][vacationIndex];
			}
			return trueFlag
				? true
				: falseFlag ? null : false;

		}

		$scope.getClassCheckCondition = (cls) => {
			const classIndex = _.indexOf($scope.data.classesIds, cls);
			let trueFlag = true;
			let falseFlag = false;
			for (let i = 0; i < $scope.data.vacations.length; i++) {
				trueFlag = trueFlag && $scope.data.classVacationMatrix[classIndex][i];
				falseFlag = falseFlag || $scope.data.classVacationMatrix[classIndex][i];
			}
			return trueFlag
				? true
				: falseFlag ? null : false;

		}

		$scope.setGradeCheckCondition = (grade, condition) => {
			const firstClassIdByGrade = _.find($scope.data.classes, (cls) => cls.grade.id === grade).id;
			const classesByGradeAmount = _.filter($scope.data.classes, (cls) => cls.grade.id === grade).length;
			const firstClassIndexByGrade = _.indexOf($scope.data.classesIds, firstClassIdByGrade);
			for (let i = firstClassIndexByGrade; i < firstClassIndexByGrade + classesByGradeAmount; i++) {
				for (let j = 0; j < $scope.data.vacations.length; j++) {
					$scope.data.classVacationMatrix[i][j] = condition;
				}
			}
			dataChanged();
		}

		$scope.setClassCheckCondition = (cls, condition) => {
			const classIndex = _.indexOf($scope.data.classesIds, cls);
			for (let i = 0; i < $scope.data.vacations.length; i++) {
				$scope.data.classVacationMatrix[classIndex][i] = condition;
			}
			$scope.data.classesChecks[classIndex] = condition;
			dataChanged();
		}

		$scope.setVacationCheckCondition = (vacation, condition) => {
			const vacationIndex = _.indexOf($scope.data.vacationsIds, vacation);
			for (let i = 0; i < $scope.data.classes.length; i++) {
				$scope.data.classVacationMatrix[i][vacationIndex] = condition;
			}
			dataChanged();
		}

		$scope.checkCell = () => {
			$scope.checkGrades();
			$scope.checkVacations();
			$scope.checkClasses();
			dataChanged();
		}

		$scope.loadMatrix = () => {
			$scope.data.classVacationMatrix = _.toArray(_.map($scope.data.classes, cls => new Array($scope.data.vacations.length)));
			_.each($scope.data.classesVacations, item => $scope.data.classVacationMatrix[_.indexOf($scope.data.classesIds, item.classId)][_.indexOf($scope.data.vacationsIds, item.vacationId)] = true);
			$scope.data.classVacationEtalonMatrix = _.toArray(_.map($scope.data.classes, cls => new Array($scope.data.vacations.length)));
			_.each($scope.data.classesVacations, item => $scope.data.classVacationEtalonMatrix[_.indexOf($scope.data.classesIds, item.classId)][_.indexOf($scope.data.vacationsIds, item.vacationId)] = true);
			$scope.checkGrades();
			$scope.checkVacations();
			$scope.checkClasses();
		}

		$scope.checkGrades = () => {
			$scope.data.gradesChecks = _.map($scope.data.grades, item => $scope.getGradeCheckCondition(item[0].grade.id));
		}

		$scope.checkVacations = () => {
			$scope.data.vacationsChecks = _.map($scope.data.vacations, item => $scope.getVacationCheckCondition(item.id));
		}

		$scope.checkClasses = () => {
			$scope.data.classesChecks = _.map($scope.data.classes, item => $scope.getClassCheckCondition(item.id));
		}

		$scope.getClassesByGrade = (grade) => {
			return _.toArray(_.filter($scope.data.classes, (item) => item.grade.id === grade));
		}

		$scope.getPrevClassGrade = (classIndex) => {
			if (classIndex === 0) {
				return -1;
			}
			return $scope.data.classes[classIndex - 1].grade.id;
		}

		$scope.matrixToClassesVacations = () => {
			let classesVacations = [];
			for (let i = 0; i < $scope.data.classVacationMatrix.length; i++) {
				for (let j = 0; j < $scope.data.classVacationMatrix[i].length; j++) {
					if ($scope.data.classVacationMatrix[i][j]) {
						classesVacations.push({ vacationId: $scope.data.vacationsIds[j], classId: $scope.data.classesIds[i] });
					}
				}
			}
			return classesVacations;
		}

		$scope.getGradeIndexById = (gradeId) => {
			for (let i = 0; i < $scope.data.grades.length; i++) {
				if ($scope.data.grades[i][0].grade.id === gradeId) {
					return i;
				}
			}
			return -1;
		}

		$scope.save = () => {
			vacationsRepository.saveClassesVacations($scope.matrixToClassesVacations(), $scope.reset);
		}

		$scope.checkCellChange = (classIndex, vacationIndex) => {
			if ($scope.data.classVacationMatrix && $scope.data.classVacationMatrix.length) {
				return ($scope.data.classVacationMatrix[classIndex][vacationIndex] && !$scope.data.classVacationEtalonMatrix[classIndex][vacationIndex]) ||
					(!$scope.data.classVacationMatrix[classIndex][vacationIndex] && $scope.data.classVacationEtalonMatrix[classIndex][vacationIndex]);
			}
			return false;
		};

		$scope.reset = (classesVacations) => {
			if (classesVacations) {
				$scope.data.classesVacations = classesVacations;
			}
			$appLoader.show();
			$scope.state.dataReady = false;
			$scope.loadMatrix();
			$scope.$applyAsync(() => {
				$scope.state.dataReady = true;
				dataWereChanged = false;
				$scope.state.emptyData = !$scope.data.classes || !$scope.data.classes.length || !$scope.data.vacations || !$scope.data.vacations.length;
				$appLoader.hide();
			});
		}

		//загрузка данных
		$scope.load = () => {
			const loadClasses = vacationsRepository.getClasses()
				.then((classes) => {
					$scope.data.classes = classes;
					$scope.data.grades = _.toArray(_.groupBy(classes, cls => cls.grade.id));
					$scope.data.classesIds = _.pluck(classes, "id");
				});

			const loadVacations = vacationsRepository.getVacations()
					.then((vacations) => {
						$scope.data.vacations = vacations;
						$scope.data.vacationsIds = _.pluck(vacations, "id");
					});

			const loadClassesVacations = vacationsRepository.getClassesVacations()
					.then((classesVacations) => {
						$scope.data.classesVacations = classesVacations;
					});


			$q.all([loadClasses, loadVacations, loadClassesVacations]).then(() => {
				$scope.reset();
			});
		}

		$(document).on("click", "button[id=resetButton]", (event) => $scope.reset());

		$(document).on("click", "button[id=saveButton]", (event) => $scope.save());

		$scope.load();
	})
	;



