"use strict";

import { BaseRepository } from "approot/global/repository/baseRepository";

export class VacationsRepository extends BaseRepository {
	getClasses() {
		return this.$http.get("/webapi/classes").then((response) => {
			const classes = response.data;
			return classes;
		});
	}

	getVacations() {
		return this.$http.get(`/webapi/calendar/vacations`, {params: {schoolYear: appContext.yearId }})
			.then((response) => {
				return response.data;
			});
	}

	getClassesVacations() {
		return this.$http.get(`/webapi/calendar/vacations/classes`, {params: {schoolYear: appContext.yearId }})
			.then((response) => {
				return response.data;
			});
	}

	saveClassesVacations(classesVacations, classesReset) {
		$(document).trigger('showProcessing');
		return this.$http.post(`/webapi/calendar/vacations/classes`, classesVacations, {params: {schoolYear: appContext.yearId }})
			.then((response) => {
				if (response.data) {
					classesReset(classesVacations);
					$(document).trigger('closeProcessing');
					$.show.message("Данные были успешно сохранены.");
				}
			},
				(response) => {
					$(document).trigger('closeProcessing');
					const msg = response.data.message || response.data.details;
					$.show.error(`<div style='overflow: auto; max-height: 400px; overflow-x: hidden;'>${msg}</div>`);
				});
	}
}

export class TermTypesRepository extends BaseRepository {
	getTermTypes() {
		return this.$http.get("/webapi/calendar/termtypes")
			.then((response) => response.data, this.handleError);
	}

	getProfiles() {
		return this.$http.get(`/webapi/curriculum/profiles`)
			.then((response) => response.data, this.handleError);
	}

	getTermTypesGrades() {
		return this.$http.get("/webapi/calendar/termtypes/grades")
			.then((response) => response.data, this.handleError);
	}

	saveTermTypesGrades(termTypesGrades) {
		$(document).trigger("showProcessing");

		return this.$http.post("/webapi/calendar/termtypes/grades", termTypesGrades)
			.then(
				(response) => {
					$(document).trigger("closeProcessing");
					return response.data;
				},
				this.handleError
			);
	}

}

export class TermsRepository extends BaseRepository {
	getTerms(sgId) {
		const params = {};
		if(sgId){
			params.sgId = sgId;
		}
		return this.$http.get("/webapi/terms", {params: params})
			.then((response) => response.data, this.handleError);
	}

	getTermInfo(termId) {
		return this.$http.get("/webapi/terms/" + termId)
			.then((response) => response.data, this.handleError);
	}

	save(terms) {
		return this.$http.post("/webapi/terms", terms)
			.catch(this.handleError);
	}

}

export class SubjectGroupsRepository extends BaseRepository {
	getEmptyIupGroups() {
		return this.$http.get("/webapi/subjectgroups/emptyIupGroups")
			.then((response) => response.data, this.handleError);
	}
}

export class SubjectsRepository extends BaseRepository {
	getSubjects(detailed) {
		let params = {};
		if (detailed) {
			params.detailed = true;
		}
		return this.$http.get("/webapi/subjects", { params: params })
			.then((response) => response.data, this.handleError);
	}

	getSubject(id) {
		return this.$http.get(`/webapi/subjects/${id}`)
			.then((response) => response.data, this.handleError);
	}

	createSubject(dto) {
		return this.$http.put(`/webapi/subjects`, dto)
			.then(this.handleResponse, this.handleError);
	}

	editSubject(dto) {
		return this.$http.post(`/webapi/subjects`, dto)
			.then(this.handleResponse, this.handleError);
	}

	orderSubjects(ids) {
		return this.$http.post("/webapi/subjects/order", null, { params: { id: ids } })
			.then((response) => response.data, this.handleError);
	}

	getSubjectCodebookInfo(id) {
		return this.$http.get(`/webapi/subjects/${id}/codebook`)
			.then((response) => response.data, this.handleError);
	}

	isCodebookUsing(subjectId, codebookId) {
		return this.$http.get(`/webapi/subjects/${subjectId}/codebook/${codebookId}/using`)
			.then((response) => response.data, this.handleError);
	}

	setSubjectCodebookInfo(id, info) {
		return this.$http.post(`/webapi/subjects/${id}/codebook`, info)
			.then((response) => response.data, this.handleError);
	}

	removeSubjects(ids) {
		$(document).trigger("showProcessing");
		return this.$http.delete("/webapi/subjects", { params: { id: ids } })
			.then(this.handleResponse, this.handleError);
	}

	getSubjectFields() {
		return this.$http.get("/webapi/subjectfields")
			.then((response) => response.data, this.handleError);
	}

	removeSubjectFields(ids) {
		$(document).trigger("showProcessing");
		return this.$http.delete("/webapi/subjectfields", { params: { id: ids } })
			.then(this.handleResponse, this.handleError);
	}

	updateSubjectField(field) {
		$(document).trigger("showProcessing");
		return this.$http.post("/webapi/subjectfields", field)
			.then(this.handleResponse, this.handleError);
	}

	createSubjectField(field) {
		$(document).trigger("showProcessing");
		return this.$http.put("/webapi/subjectfields", field)
			.then(this.handleResponse, this.handleError);
	}

	editGroup(subjectId, group) {
		$(document).trigger("showProcessing");
		return this.$http.post(`/webapi/subjects/${subjectId}/groups`, group)
			.then(this.handleResponse, this.handleError);
	}

	createGroup(subjectId, group) {
		$(document).trigger("showProcessing");
		return this.$http.put(`/webapi/subjects/${subjectId}/groups`, group)
			.then(this.handleResponse, this.handleError);
	}

	deleteGroup(subjectId, ids) {
		$(document).trigger("showProcessing");
		return this.$http.delete(`/webapi/subjects/${subjectId}/groups`, { params: { id: ids } })
			.then(this.handleResponse, this.handleError);
	}

	getTeachers(id, used) {
		let params = {};
		if (used) {
			params.used = used;
		}
		return this.$http.get(`/webapi/subjects/${id}/teachers`, { params: params })
			.then((response) => response.data, this.handleError);
	}

	setTeachers(id, teacherIds) {
		return this.$http.post(`/webapi/subjects/${id}/teachers`, null, { params: { teacherId: teacherIds } })
			.then((response) => response.data, this.handleError);
	}

	getParentSubjects() {
		return this.$http.get("/webapi/parentsubjects")
			.then((response) => response.data, this.handleError);
	}
}

export class EventsRepository extends BaseRepository {
	getEventsTypes() {
		return this.get("/webapi/events/types");
	}

	getEventsClasses() {
		return this.get("/webapi/events/classes");
	}


	getEventsRooms() {
		return this.get("/webapi/rooms/short");
	}

	getEvents(type, classId) {
		return classId
			? this.get(`/webapi/events/${type}/${classId}`)
			: this.get(`/webapi/events/${type}/!`); // Заглушка вызова метода. Метод пересекается с другим
	}

	getEvent(eventId) {
		return this.get(`/webapi/events/${eventId}`);
	}

	createEvent(eventDto) {
		return eventDto.id
			? this.$http.post("/webapi/events", eventDto)
			: this.$http.post("/webapi/events/new", eventDto);
	}

	deleteEvent(event) {
		let options = { params: { eventId: event.id } };
		return this.$http.delete("/webapi/events", options);
	}

	getPermission(eventType, classId){
		let options = {
			eventType: eventType
		}
		if(classId) options.classId = classId;
		return this.$http.post("/webapi/event/permission", null, {params:options})
	}
}

export class CurriculumRepository extends BaseRepository {
	getLimits(iup) {
		let params = {};
		if (iup) {
			params.iup = true;
		}

		return this.get("/webapi/curriculum/limits", { params: params });
	}

	getGrades() {
		return this.get("/webapi/curriculum/grades");
	}

	getHoursCount(sgId, termId) {
		return this.get("/webapi/curriculum/hours/count", { params: { sgId, termId } });
	}

	getComponents(iup) {
		let params = {};
		if (iup) {
			params.iup = true;
		}

		return this.get("/webapi/curriculum/components", { params: params });
	}

	createComponent(component) {
		return this.$http.put("/webapi/curriculum/components", component)
			.then(() => { this.$alerts.success(language.Generic.SetupSchoolCalendar.kComponentCreated); })
			.catch(this.handleError);
	}

	deleteComponents(components) {
		let params = { id: components };

		return this.$http.delete("/webapi/curriculum/components", { params: params })
			.then(() => { this.$alerts.success(language.Generic.SetupSchoolCalendar.kComponentsDeleted); })
			.catch(this.handleError);
	}

	saveLimits(limits, iup) {
		let params = {};
		if (iup) {
			params.iup = iup;
		}

		$(document).trigger("showProcessing");

		return this.$http.post("/webapi/curriculum/limits", limits, { params: params })
			.then(() => {
				$(document).trigger("closeProcessing");
				this.$alerts.success(language.Generic.Common.kDataSaved);
			})
			.catch(this.handleError);
	}
}

export class ProfilesRepository extends BaseRepository {

	getProfiles() {
		return this.get("/webapi/curriculum/profiles").catch(this.handleError);
	}

	getProfileGradeClassList() {
		return this.get("/webapi/curriculum/getProfileGradeClassList").catch(this.handleError);
	}

	saveProfiles(profiles){
		return this.$http.post("/webapi/curriculum/save",profiles ).catch(this.handleError);
	}

	deleteProfile(profiles){
		return this.$http.post("/webapi/curriculum/delete",profiles ).catch(this.handleError);
	}

	isNotAllGradesHasTerms(){
		return this.get("/webapi/curriculum/isNotAllGradesHasTerms").catch(this.handleError);
	}
}


