const module = angular.module("irtech.netcity.school.calendar",
[
	"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap", "ngFileUpload", "ui.tree",
	"irtech.netcity.common", "irtech.netcity.ui-components"
]);

require("./vacations/classesRelations/vacationsClassesCtrl.js");

import { VacationsRepository, EventsRepository } from "./repository.js";

require("./events/eventsCtrl.js");
require("approot/global/directives/storageDirective.coffee");
 
module
	.service("vacationsRepository", VacationsRepository)
	.service("eventsRepository", EventsRepository)
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
		.when("/vacations/classesRel/", {
			templateUrl: "/static/dist/app/school/calendar/vacations/classesRelations/template.html",
			controller: "VacationsClassesCtrl"
		})
		.when("/events/edit/:eventId", {
			templateUrl: "/static/dist/app/school/calendar/events/edit/sheetTemplate.html",			
			controller: "SheetEditEventController"
		})
		.when("/events/:eventType", {			
			templateUrl: "/static/dist/app/global/templates/registry.html",
			controller: "EventsCtrl"
		})
		.when("/events/", {
			//templateUrl: "/static/dist/app/school/calendar/events/template.html",
			templateUrl: "/static/dist/app/global/templates/registry.html",
			controller: "EventsCtrl"
		})
		.otherwise({
			templateUrl: "/static/dist/app/school/calendar/vacations/classesRelations/template.html",
			controller: "VacationsClassesCtrl"
		})
	;
	$locationProvider.hashPrefix('');
	$locationProvider.html5Mode({
		enabled: true,
		requireBase: true
	});
});


