"use strict";
require("approot/global/controllers/registryCtrl.js");
import * as Rights from "approot/global/references/rights.js";

let devDebug = (...args) => window.appContext.environment === "dev" && console.debug(...args);

/* контроллер реестра */
const eventsCtrl = ($scope, $http, $document, $location, $appLoader, $alerts, $uibModal, $controller, eventsRepository, $routeParams) => {
	$scope.language = language;
	$scope.$parent.page = {
		title: language.Generic.SetupSchoolCalendar.kTitleEvents,
		parent: {
			title: language.Generic.MenuFolders.kFNSchoolYearAndTerms,
			href: `/asp/SetupSchool/Calendar/Years.asp`
		},
		back: { history: true }
	};
	$scope.readonly = null;

	let hideButtons = (readonly) => {
		let buttons = $(".btn");
		let addButton = buttons.has(".glyphicon-plus-sign");
		let deleteButtons = buttons.has(".glyphicon-minus-sign");
		if (readonly) {
			addButton.hide();
			deleteButtons.hide();
		} else {
			addButton.show();
			deleteButtons.show();
		}
	}

	$scope.$watch("readonly", (readonlyValue, oldReadonlyValue) => {
		if (readonlyValue === oldReadonlyValue) {
			return;
		}

		hideButtons(readonlyValue);
	});

	let getChangeEventTypeHandler = () => {
		let oldEventType;
		let oldClassId;

		return (eventType, classId) => {
			if (classId == -1) {
				classId = null;
			}

			if (oldEventType == eventType && oldClassId == classId) return;
			oldEventType = eventType;
			oldClassId = classId;

			eventsRepository.getPermission(eventType, classId)
				.then((response) => $scope.readonly = response.data);
		}
	};
	let changeEventType = getChangeEventTypeHandler();

	$(document).on("EventFilter:change", (event, newEventTypeValue, oldValue, filter) => {
		var classId = getFilterById("ClassFilter").choice;
		changeEventType(newEventTypeValue, classId);
	});
	$(document).on("ClassFilter:change", (event, newClassIdValue, oldValue, filter) => {
		var eventType = getFilterById("EventFilter").choice;
		changeEventType(eventType, newClassIdValue);
	});

	let filterPanelEventHandler = (eventInfo, filterPanel) => {
		let filters = filterPanel.filters;
		let eventfilter = filters.filter((f) => f.id == "EventFilter")[0];
		let classFilter = filters.filter((f) => f.id == "ClassFilter")[0];

		if ($routeParams.eventType) {
			let eventType = $routeParams.eventType;
			eventfilter.setChoice(eventType);
			/*
			setTitle(eventType);

			let eventTypeFilter = $("[name=EventFilter]");
			if(window.appContext.environment === "dev"){
				eventTypeFilter.prop("disabled", true);
			}else{
				eventTypeFilter.parents(".form-group").hide();
			}
			*/
		}

		changeEventType(eventfilter.choice, classFilter.choice);
	}
	$scope.$on("FilterPanelInitialized", filterPanelEventHandler);

	let setTitle = (eventType) => {
		const titles = {
			1: language.SetupSchoolCalendar.kSchoolEvents, //SchoolEvent
			2: language.SetupSchoolCalendar.kClassEvents, //ClassEvents
			3: language.Generic.SetupSchoolCalendar.kVacations, //Vacations
			4: language.Generic.SetupSchoolCalendar.kHolidays, //Holidays
		};
		$scope.$parent.page.title = titles[eventType] || $scope.$parent.page.title;
	}

	let getFilterById = (filterId) => $scope.filterInfo.filterPanel.filters.filter((f) => f.id == filterId)[0];

	let getEvent = (eventId) => eventsRepository.getEvent(eventId)
		.then((event) => {
			event.periodicity = event.periodicity.toString();
			event.startTime = Date.parse(event.startTime);
			event.endTime = Date.parse(event.endTime);

			devDebug(event);
			return event;
		}, eventsRepository.handleError);

	let openNewModal = (eventData) => {
		let isNewEvent = !eventData;
		let title = isNewEvent ? language.Generic.SetupSchoolCalendar.kAddEvent : language.Generic.SetupSchoolCalendar.kEditEvent;

		let modal = $uibModal.open({
			title: language.Generic.SetupSchoolCalendar.kEditEvent, // !<-- как этим пользоваться?
			templateUrl: "/static/dist/app/school/calendar/events/edit/modalTemplate.html",
			size: "md",
			controller: "ModalEditEventController",
			resolve: {
				title: () => title,
				event: () => eventData || {},
				eventTypeId: () => getFilterById("EventFilter").choice,
				classId: () => getFilterById("ClassFilter").choice,
			}
		});

		modal.result
			.then((result) => devDebug(result))
			.then(() => $scope.load());
	}

	$scope.editEvent = (event) => {
		if (event)
			getEvent(event.id).then(openNewModal);
		else
			openNewModal();
	}

	const addBtn = {
		id: "addBtn",
		title: language.Generic.Buttons.kAdd,
		icon: "glyphicon glyphicon-plus-sign",
		action: $scope.editEvent
	}

	$scope.registry = {
		url: "/webapi/school/events/registry",
		filtersUrl: "/webapi/school/events/registry/filter",
		fieldDecorators: {
			"name": { type: "link", action: $scope.editEvent }
		},
		buttons: [addBtn]
	};

	$controller("RegistryCommonCtrl", { $scope, $http, $document, $location, $appLoader, $uibModal, $alerts });
}

/* Контроллер редактирования */
let editEventController = ($scope, eventsRepository, $alerts, $q, event, afterSaveHandler, afterCancelHandler, predefined) => {
	$scope.language = language;
	$scope.model = event;
	$scope.model.periodicity = $scope.model.periodicity || "false";
	$scope.readonly = true;

	predefined = predefined || {};

	$scope.formatDate = (date) => {
		if (!date) return;

		const options = {
			//era: 'long',
			year: "numeric",
			month: "long",
			day: "numeric",
			weekday: "long"
		};

		const hasTime = (date) => date.getHours() || date.getMinutes();
		if (hasTime(date)) {
			angular.extend(options,
				{
					timezone: "UTC",
					hour: "numeric",
					minute: "numeric",
					//second: 'numeric'
				});
		}

		return date.toLocaleString("ru", options);
	}

	let isDateOnly = () => ["Vacations", "Holidays"].indexOf($scope.model.eventType) >= 0;
	$scope.startDateName = () => isDateOnly() ? $scope.language.Generic.Common.kStartDate : $scope.language.Generic.Common.kStartTime;
	$scope.endDateName = () => isDateOnly() ? $scope.language.Generic.Common.kEndDate : $scope.language.Generic.Common.kEndTime;

	let getPermission = () => {
		if (!$scope.model.eventType) {
			return Promise.resolve();
		}
		return eventsRepository.getPermission($scope.model.eventType, $scope.model.class && $scope.model.class.id)
			.then((response) => $scope.readonly = response.data, () => $scope.readonly = true);
	}

	$scope.periodicity = {
		"true": language.Generic.SetupSchoolCalendar.kYearPeriod,
		"false": language.Generic.SetupSchoolCalendar.kNotPeriodicity
	}

	let hasError = (object) => object.$invalid && (!object.$pristine || object.$displayErrors);
	$scope.hasError = hasError;
	$scope.hasErrorClass = (object) => {
		return { 'has-error': hasError(object) }
	}

	let getClasses = () => {
		let needClasses = ["ClassEvents"].indexOf($scope.model.eventType) > -1;
		if (!needClasses) return Promise.resolve();

		return eventsRepository.getEventsClasses()
			.then((result) => {
				$scope.classes = result;

				let predefinedClass = _.filter($scope.classes, (o) => o.id == predefined.classId)[0];

				$scope.model.class = $scope.model.class || predefinedClass;

				return $scope.classes;
			})
			.then((classes) => devDebug("classes:", classes));
	}

	let needRooms = false;
	const noRoom = { id: null, name: language.Generic.Common.kNo };
	$scope.rooms = [noRoom];
	let getRooms = () => {
		needRooms = ["SchoolEvent", "ClassEvents"].indexOf($scope.model.eventType) > -1;
		if (!needRooms || $scope.readonly) return Promise.resolve();

		return eventsRepository.getEventsRooms()
			.then((result) => $scope.rooms = [noRoom, ...result]);
	}

	$scope.onChangeType = () => {
		return getClasses()
			.then(getPermission)
			.then(getRooms);
	}

	eventsRepository.getEventsTypes()
		.then((eventsTypes) => {
			//убираем не внутришкольные события
			$scope.eventsTypes = _.filter(eventsTypes, (t) => t.key !== "AwardEvents");

			let predefinedEvent = _.filter($scope.eventsTypes, (o) => o.id == predefined.eventTypeId)[0];
			let predefinedEventKey = predefinedEvent && predefinedEvent.key;

			$scope.model.eventType = $scope.model.eventType || predefinedEventKey || $scope.eventsTypes[0].key;

			devDebug("Events types", $scope.eventsTypes);
		})
		.then($scope.onChangeType)
		.then(() => {
			//после первого получения, добавляем отслеживание изменений
			const permissionWatcher = (newValue, oldValue) => {
				if (newValue !== oldValue) getPermission();
			}
			$scope.$watch("model.class", permissionWatcher);
		});

	$scope.cancel = () => {
		afterCancelHandler("cancel");
	};

	$scope.ok = () => {
		let valide = true;

		if ($scope.form.$error && $scope.form.$error.required) {
			angular.forEach($scope.form.$error.required, field => field.$setDirty());
			valide = false;
		}

		if (!valide) return;

		// Решает проблему с "установки текущей даты" вместо пустого поля (неожиданное поведение форматтера DateInput`а)
		if (!document.querySelector('#endTime #dateInput').value) {
			$scope.model.endTime = $scope.model.startTime;
		}

		const dropSeconds = (date) => {
			date.setSeconds(0);
			date.setMilliseconds(0);
		};

		dropSeconds($scope.model.startTime);
		dropSeconds($scope.model.endTime);

		if ($scope.model.endTime && $scope.model.startTime > $scope.model.endTime) {
			$alerts.error("Дата начала мероприятия должна быть раньше даты окончания");
			valide = false;
		}

		if (!valide) return;

		let copyEventModel = angular.copy($scope.model);

		if (!copyEventModel.endTime) {
			copyEventModel.endTime = copyEventModel.startTime;
		}

		// Подготовка дат к передаче
		if (copyEventModel.eventType === "ClassEvents" || copyEventModel.eventType === "SchoolEvent") {
			copyEventModel.startTime = dateUtils.asUTC(copyEventModel.startTime);
			copyEventModel.endTime = dateUtils.asUTC(copyEventModel.endTime);
		} else {
			copyEventModel.startTime = dateUtils.asUTCDate(copyEventModel.startTime);
			copyEventModel.endTime = dateUtils.asUTCDate(copyEventModel.endTime);
		}

		if (copyEventModel.eventType === "Holidays") {
			copyEventModel.schoolYearId = window.appContext.yearId;
		}

		if (needRooms && copyEventModel.room.id == noRoom.id) {
			copyEventModel.room = null;
		}

		eventsRepository.createEvent(copyEventModel)
			.then(() => afterSaveHandler(copyEventModel), eventsRepository.handleError)
			.then(() => $alerts.success(["Holidays", "Vacations"].indexOf(copyEventModel.eventType) > -1
				? language.Generic.Common.kDataSaved
				: language.Generic.Events.kEventSaved));
	};

	$scope.get = (source, key, keyColumn, resultColumn) => {
		if (!source) return;
		let result = source.find((val) => val[keyColumn] == key);
		if (!result) return;
		return result[resultColumn];
	};
}

/* Контролер полной страницы */
let sheetEditEventController = ($scope, eventsRepository, $alerts, $q, $routeParams, $appLoader, $window, $dialogs, $http) => {
	devDebug($routeParams);

	$scope.$parent.page = {
		title: language.Generic.SetupSchoolCalendar.kTitleEvents,
		parent: appContext.hasAnyRight([Rights.arMoveBookEdit, Rights.arCreateCloseEditYear, Rights.arCreateEditTerm])
			? {
				title: language.Generic.MenuFolders.kFNSchoolYearAndTerms,
				href: `/years/`
			}
			: null,
		back: { history: true }
	};

	let leave = () => {
		const backInfo = $scope.page.back;
		if (backInfo && backInfo.history) {
			//браузерный бэк
			if ($window.routeChanges > 1) {
				$window.history.back();
			} else {
				window.postTo(document.referrer);
			}
			return;
		}

		const backHref = (backInfo && backInfo.href) || ($scope.page.parent && $scope.page.parent.href);
		if (backHref) {
			if (backHref.indexOf(".asp") > 0) {
				//если указан href на asp страницу
				checkForChanges().then(() => window.postTo(backHref));

			} else {
				//если указан href - angular страницу
				$location.path(backHref);
				$scope.$apply();
			}

			return;
		}
	}

	let saveHandler = leave;
	let cancelHandler = leave;

	$scope.hasValue = !!Number($routeParams.eventId);

	if ($scope.hasValue) {
		// load and show
		eventsRepository.getEvent($routeParams.eventId)
			.then((event) => {
				event.periodicity = event.periodicity.toString();
				event.startTime = Date.parse(event.startTime);
				event.endTime = Date.parse(event.endTime);

				devDebug(event);
				return event;
			}, eventsRepository.handleError)
			.then((event) => editEventController($scope, eventsRepository, $alerts, $q, event, saveHandler, cancelHandler))
			.then(() => $appLoader.hide());
	}
	else {
		// empty event
		let event = {}
		if ($routeParams.eventDate) {
			const getDate = (val) => {
				let date = str2date(val);
				date.setHours(0);
				date.setMinutes(0);
				return date;
			}
			event.startTime = getDate($routeParams.eventDate);
			event.endTime = getDate($routeParams.eventDate);
		}
		if($routeParams.class){
			event.class = {
				id: $routeParams.class
			}
		}
		event.periodicity = "false";
		devDebug(event);

		let predefined = {
			eventTypeId: $routeParams.eventType
		}

		editEventController($scope, eventsRepository, $alerts, $q, event, saveHandler, cancelHandler, predefined);
		$appLoader.hide();
	}

	$scope.delete = () => {
		let confirm = language.Generic.SetupSchoolCalendar.kDeleteSingleEventConfirm;
		const confirms = [$.show.getConfirmation(confirm)];

		extDeferred.when(confirms).then(() => {
			const wait = $dialogs.wait("Операция выполняется");
			const data = {
				itemId: [$routeParams.eventId]
			};

			$http.post(`/webapi/school/events/registry/command/del`, null, { params: data })
				.then(
					(response) => {
						wait.close();
						const result = response.data;
						if (result.success) {
							$.show.message(result.message);
							leave();
						} else {
							$.show.error(result.message);
						}
					},
					(response) => {
						$.show.error(response.data && response.data.message, "Ошибка выполнения команды");
						wait.close();
					});
		});
	};
}

/* Контроллер модального окна */
let modalEditEventController = ($scope, $uibModalInstance, $q, title, event, eventsRepository, $alerts, eventTypeId, classId, $controller, $dialogs, changeTracker) => {
	$scope.title = title;
	let saveHandler = (model) => $uibModalInstance.close(model);
	let cancelHandler = (reason) => $uibModalInstance.dismiss(reason);
	let preset = { eventTypeId, classId };

	editEventController($scope, eventsRepository, $alerts, $q, event, saveHandler, cancelHandler, preset);
};

let timeInputDirective = () => {
	let linkFunk = ($scope, element, attr, controller) => {
		let timerid;
		const timer = () => {
			clearTimeout(timerid);
			const timeoutFunc = () => {
				$scope._hours = $scope._hours || 0;
				$scope._minutes = $scope._minutes || 0;

				if (!$scope.model) $scope.model = new Date();
				$scope.model.setHours($scope._hours);
				$scope.model.setMinutes($scope._minutes);

				//$scope.$emit("dateChange".toUpperCase(), (value) => controller.$setValidity("crossDatesError", value));
			}
			timerid = setTimeout(timeoutFunc, 750);
		}

		let range = (upperLimit, step) => {

			let count = Math.floor(upperLimit / step);
			return [...Array(count).keys()]
				.map(i => i * step)
				// `${i}` hack i.toString()
				.map(i => {return {id:i, value: `${i}`.padStart(2, '0')}});

		}

		$scope.hours = range(24, 1);
		$scope.minutes = range(60, 5);

		$scope.$watch("_hours", timer);
		$scope.$watch("_minutes", timer);
		$scope.$watch("model", (newValue) => {
			if (newValue && newValue.getHours) {
				$scope._hours = newValue.getHours();
				$scope._minutes = newValue.getMinutes();
			}
			return newValue;
		});
	}

	return {
		restrict: "E",
		require: "ngModel",
		replace: false,
		scope: {
			model: "=ngModel"
		},
		link: linkFunk,
		templateUrl: "/static/dist/app/school/calendar/events/edit/timeInputTemplate.html"
	}
}

angular
	.module("irtech.netcity.school.calendar")
	.controller("EventsCtrl", eventsCtrl)
	.controller("ModalEditEventController", modalEditEventController)
	.controller("SheetEditEventController", sheetEditEventController)
	.directive("timeInput", timeInputDirective)
	;


